{
  "rule_id": "R-INTEREST-001",
  "type": "late_payment_interest",
  "title": "Late Payment Interest",
  "source": {
    "page": 1,
    "section": "3.1",
    "text": "Late payments beyond thirty (30) days..."
  },
  "conditions": [
    {
      "variable": "payment_delay_days",
      "operator": ">",
      "value": 30,
      "unit": "days"
    }
  ],
  "actions": [
    {
      "type": "interest",
      "rate": 0.015,
      "period": "month",
      "grace_period_days": 30,
      "base_variable": "invoice_amount"
    }
  ],
  "caps": {
    "max_percentage": 0.15,
    "max_amount": null
  }
}

{
  "rule_id": "R-PENALTY-002",
  "type": "delivery_delay_penalty",
  "title": "Delivery Delay Liquidated Damages",
  "source": {
    "page": 2,
    "section": "5.2",
    "text": "If delivery is delayed past the agreed milestone date..."
  },
  "conditions": [
    {
      "variable": "delivery_delay_days",
      "operator": ">",
      "value": 10,
      "unit": "days"
    }
  ],
  "actions": [
    {
      "type": "penalty",
      "rate": 0.02,
      "period": "week",
      "grace_period_days": 10,
      "base_variable": "contract_value"
    }
  ],
  "caps": {
    "max_percentage": 0.1,
    "max_amount": null
  }
}

{
  "rule_id": "R-DISCOUNT-003",
  "type": "volume_discount",
  "title": "Volume Price Discount",
  "source": {
    "page": 2,
    "section": "4.1",
    "text": "Buyer shall be entitled to a 5% volume discount..."
  },
  "conditions": [
    {
      "variable": "order_quantity",
      "operator": ">=",
      "value": 1000,
      "unit": "units"
    }
  ],
  "actions": [
    {
      "type": "discount",
      "rate": 0.05,
      "base_variable": "contract_value"
    }
  ],
  "caps": {
    "max_percentage": null,
    "max_amount": null
  }
}

{
  "rule_id": "R-SLA-004",
  "type": "sla_penalty",
  "title": "SLA Availability Breach Penalty",
  "source": {
    "page": 4,
    "section": "8.3",
    "text": "Should monthly service availability fall below 99.5%..."
  },
  "conditions": [
    {
      "variable": "sla_uptime_percent",
      "operator": "<",
      "value": 99.5,
      "unit": "%"
    }
  ],
  "actions": [
    {
      "type": "sla_deduction",
      "amount": 5000.0,
      "base_variable": "monthly_invoice"
    }
  ],
  "caps": {
    "max_percentage": null,
    "max_amount": 50000.0
  }
}

{
  "rule_id": "R-ESCALATION-005",
  "type": "price_escalation",
  "title": "Inflation Price Escalation",
  "source": {
    "page": 6,
    "section": "12.1",
    "text": "Unit pricing shall increase by 3.5% annually..."
  },
  "conditions": [
    {
      "variable": "inflation_rate_percent",
      "operator": ">",
      "value": 2.0,
      "unit": "%"
    }
  ],
  "actions": [
    {
      "type": "escalation",
      "rate": 0.035,
      "base_variable": "contract_value"
    }
  ],
  "caps": {
    "max_percentage": null,
    "max_amount": null
  }
}
